import itertools, random, sys
sys.path.insert(0, "src")
from accountability.authorization import intersection_pattern, pattern_matches

random.seed(42)
ALPHABET = "ab"

def gen_pattern():
    n = random.randint(1, 5)
    parts = []
    for _ in range(n):
        parts.append("".join(random.choice(ALPHABET) for _ in range(random.randint(0, 2))))
    return "*".join(parts)

def brute_intersects(p1, p2, maxlen=10):
    # enumerate strings over alphabet a,b,c up to maxlen
    for L in range(0, maxlen + 1):
        for tup in itertools.product("abc", repeat=L):
            s = "".join(tup)
            if pattern_matches(p1, s) and pattern_matches(p2, s):
                return True
    return False

bad = 0
for trial in range(4000):
    p1, p2 = gen_pattern(), gen_pattern()
    r12 = intersection_pattern(p1, p2)
    r21 = intersection_pattern(p2, p1)
    if r12 != r21:
        print("DIRECTION ASYMMETRY:", p1, p2, r12, r21); bad += 1
    bi = brute_intersects(p1, p2)
    if (r12 is not None) != bi:
        print("INTERSECT MISMATCH:", p1, p2, "code:", r12, "brute:", bi); bad += 1
    if r12 is not None:
        # soundness: every match of result matches both (sample)
        for L in range(0, 9):
            for tup in itertools.product("abc", repeat=L):
                s = "".join(tup)
                if pattern_matches(r12, s) and not (pattern_matches(p1, s) and pattern_matches(p2, s)):
                    print("UNSOUND MERGE:", p1, p2, r12, "counterexample:", repr(s)); bad += 1
    if bad > 10:
        break
print("done, bad =", bad)
