import itertools, random, sys
from functools import lru_cache
sys.path.insert(0, "src")
from accountability.authorization import (
    intersection_pattern, _split_glob, _middle_runs_compatible, _merge_middle_runs,
)

random.seed(7)

def gen_run():
    n = random.randint(0, 4)
    return tuple("".join(random.choice("ab") for _ in range(random.randint(1, 2)))
                 for _ in range(n))

def embeds(run, seq):
    """Is run a subsequence of seq?"""
    it = iter(seq)
    return all(any(x == y for y in it) for x in run)

def ref_compatible(r1, r2):
    """Independent reference: BFS over common supersequences with exact max counts."""
    from collections import Counter, deque
    c1, c2 = Counter(r1), Counter(r2)
    cap = {f: max(c1.get(f, 0), c2.get(f, 0)) for f in set(c1) | set(c2)}
    total = sum(cap.values())
    frags = list(cap)
    # state: (i, j, counts_used_tuple) — BFS building sequence
    start = (0, 0, tuple([0] * len(frags)))
    seen = {start}
    dq = deque([start])
    while dq:
        i, j, used = dq.popleft()
        if i == len(r1) and j == len(r2):
            if sum(used) == total:
                return True
            continue
        for k, f in enumerate(frags):
            if used[k] >= cap[k]:
                continue
            ni, nj = i, j
            if ni < len(r1) and r1[ni] == f:
                ni += 1
            if nj < len(r2) and r2[nj] == f:
                nj += 1
            if ni == i and nj == j:
                continue
            nu = list(used); nu[k] += 1; nu = tuple(nu)
            st = (ni, nj, nu)
            if st not in seen:
                seen.add(st)
                dq.append(st)
    return False

bad = 0
for t in range(3000):
    r1, r2 = gen_run(), gen_run()
    got = _middle_runs_compatible(r1, r2)
    want = ref_compatible(r1, r2)
    if got != want:
        print("COMPAT MISMATCH:", r1, r2, "code:", got, "ref:", want)
        bad += 1
    if got:
        m = _merge_middle_runs(r1, r2)
        m2 = _merge_middle_runs(r2, r1)
        if m != m2:
            print("MERGE ASYMMETRY:", r1, r2, m, m2); bad += 1
        from collections import Counter
        cm, c1, c2 = Counter(m), Counter(r1), Counter(r2)
        for f in set(c1) | set(c2):
            if cm.get(f, 0) != max(c1.get(f, 0), c2.get(f, 0)):
                print("MERGE COUNT WRONG:", r1, r2, m); bad += 1
        if not (embeds(r1, m) and embeds(r2, m)):
            print("MERGE NOT SUPERSEQUENCE:", r1, r2, m); bad += 1
    if bad > 10:
        break
print("done, bad =", bad)
